(async () => {
  const J = {'Content-Type': 'application/json', 'X-Gigg-CSRF': '1'};
  const me = await (await fetch('/api/v1/auth/me')).json();
  const users = (await (await fetch('/api/v1/users?limit=50')).json()).items || [];
  const scout = users.find(u => u.username === 'scout');
  const ids = [me.user.id].concat(scout ? [scout.id] : []);
  const due = Date.now() + 3 * 86400000;
  const r = await fetch('/api/v1/projects/1/gigs', {method: 'POST', headers: J, body: JSON.stringify({
    title: 'Panel check: a gig with every setting filled in', priority: 3, color: '#3E63DD', labels: ['runtime-scan', 'ui'],
    assignees: ids, followers: ids, due_at: due, checklist: ['Read the spec', 'Build it', 'Test it'],
    description_md: 'A gig to look at the **panel** with: labels, people, dates, a checklist and run settings.\n\n- one\n- two'})});
  const g = await r.json();
  await fetch('/api/v1/gigs/' + g.id, {method: 'PATCH', headers: J, body: JSON.stringify({model: 'opus', effort: 'high'})});
  await fetch('/api/v1/gigs/' + g.id + '/comments', {method: 'POST', headers: J, body: JSON.stringify({body_md: 'Started on it.'})});
  localStorage.setItem('panelGig', g['key']);
  return r.status;
})()
